using Microsoft.AspNetCore.Mvc;

namespace EnquiryBackend.Controllers;

[ApiController]
[Route("api/[controller]")]
public class ChatController : ControllerBase
{
    private readonly ChatOrchestrator _orchestrator;

    public ChatController(ChatOrchestrator orchestrator)
    {
        _orchestrator = orchestrator;
    }

    // POST /api/chat
    [HttpPost]
    public async Task<ActionResult<ChatResponse>> Post([FromBody] ChatRequest request, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(request.Message))
        {
            return BadRequest(new { error = "message is required" });
        }

        var reply = await _orchestrator.GenerateReplyAsync(request, ct);
        return Ok(reply);
    }

    // GET /api/chat/health
    [HttpGet("health")]
    public ActionResult Health() => Ok(new { status = "ok" });
}

