using EnquiryBackend.Models;

namespace EnquiryBackend.Services;

public sealed class ChatOrchestrator
{
    private readonly IReadOnlyDictionary<Provider, IChatProvider> _providers;
    private readonly ILogger<ChatOrchestrator> _logger;

    public ChatOrchestrator(
        GroqChatProvider groq,
        GeminiChatProvider gemini,
        OpenAiChatProvider openAi,
        ILogger<ChatOrchestrator> logger)
    {
        _providers = new Dictionary<Provider, IChatProvider>
        {
            [Provider.Groq] = groq,
            [Provider.Gemini] = gemini,
            [Provider.OpenAI] = openAi
        };
        _logger = logger;
    }

    public async Task<ChatResponse> GenerateReplyAsync(ChatRequest request, CancellationToken ct)
    {
        // Tier 1: deterministic rule engine â€” no API key needed at all.
        var ruleReply = RuleEngine.TryGetReply(request.Message);
        if (ruleReply is not null)
        {
            return new ChatResponse { Reply = ruleReply, Source = "rule" };
        }

        // Tier 2: whichever provider the frontend selected, using the key
        // pasted into that provider's "API key" field.
        if (!string.IsNullOrWhiteSpace(request.ApiKey) && _providers.TryGetValue(request.Provider, out var provider))
        {
            try
            {
                var systemPrompt = PersonalityPrompt.BuildSystemPrompt(request.Tone);
                var reply = await provider.GenerateReplyAsync(systemPrompt, request.Message, request.ApiKey, ct);
                return new ChatResponse { Reply = reply, Source = request.Provider.ToString() };
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "{Provider} failed, falling back.", request.Provider);
            }
        }

        // Tier 3: hard fallback â€” mirrors "Will reply later" in ai_engine.py.
        return new ChatResponse { Reply = "Will reply later", Source = "fallback" };
    }
}

