namespace EnquiryBackend.Services;

public static class RuleEngine
{
    // Seasonal weather data for Keshod, India (same table as ai_engine.py)
    private static readonly Dictionary<int, string> WeatherByMonth = new()
    {
        [1] = "Around 15-28Â°C these days.",
        [2] = "Around 18-30Â°C these days.",
        [3] = "Getting warmer, around 25-36Â°C.",
        [4] = "Proper summer now, 32-42Â°C easily.",
        [5] = "Proper summer now, 32-42Â°C easily.",
        [6] = "Mostly humid and monsoon vibes.",
        [7] = "Mostly humid and monsoon vibes.",
        [8] = "Mostly humid and monsoon vibes.",
        [9] = "Mostly humid and monsoon vibes.",
        [10] = "Pleasant weather, around 25-35Â°C.",
        [11] = "Comfortable, around 20-30Â°C.",
        [12] = "Cooler side, around 15-28Â°C."
    };

    private static readonly string[] WeatherKeywords =
        ["weather", "temperature", "forecast", "mausam", "garmi", "thandi"];

    private static readonly string[] NonVegKeywords =
        ["chicken", "mutton", "fish", "non veg", "non-veg"];

    private static readonly string[] MarketKeywords =
        ["market", "nifty", "sensex", "stock"];

    /// <summary>
    /// Fast deterministic rules checked before hitting any LLM.
    /// Returns null if no rule matches, meaning the caller should
    /// fall through to the selected AI provider.
    /// </summary>
    public static string? TryGetReply(string rawMessage)
    {
        var msg = rawMessage.Trim().ToLowerInvariant();
        var month = DateTime.Now.Month;

        if (WeatherKeywords.Any(msg.Contains))
        {
            return WeatherByMonth.GetValueOrDefault(month);
        }

        if (msg is "hi" or "hello" or "hey")
        {
            return "Hello.";
        }

        if (msg.Contains("good morning"))
        {
            return "Good morning, have a productive day.";
        }

        if (msg.Contains("good night"))
        {
            return "Good night, sleep well.";
        }

        if (NonVegKeywords.Any(msg.Contains))
        {
            return "I stick to veg, yaar.";
        }

        if (MarketKeywords.Any(msg.Contains))
        {
            return "Market is volatile these days, need patience.";
        }

        if (msg.Length <= 2)
        {
            return "Can you explain properly?";
        }

        return null;
    }
}

