          aria-label="Open settings"
          aria-expanded={settingsOpen}
          onClick={() => setSettingsOpen((currentValue) => !currentValue)}
        >
          <span />
          <span />
          <span />
        </button>
      </header>

      <main className={workspaceClass}>
        <section className="avatar-panel">
          <div
            className={isSpeaking ? 'avatar-shell speaking' : 'avatar-shell'}
          >
            <div className="avatar-border" />
            <div
              className={isSpeaking ? 'avatar-glow speaking' : 'avatar-glow'}
            />
            <div
              className={isSpeaking ? 'avatar-ring speaking' : 'avatar-ring'}
            />

            <div className="avatar-float">
              <div className="avatar-breathe">
                <div
                  className={
                    isSpeaking ? 'avatar-head speaking' : 'avatar-head'
                  }
                >
                  <div className="avatar-frame">
                    {avatarMode === 'Photo' ? (
                      <img
                        className="avatar-photo"
                        src={avatarImage}
                        alt={`${avatarGender} avatar`}
                        loading="eager"
                        decoding="async"
                        draggable="false"
                      />
                    ) : (
                      //  {isSpeaking  && <div className="mouth-overlay" />}
                      <div className="avatar-3d-placeholder">
                        <AvatarCanvas isSpeaking={isSpeaking} />
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <div className="avatar-caption mb-2">
              <span className="status">
                {' '}
                {isThinking
                  ? 'Thinking...'
                  : isSpeaking
                    ? 'Speaking'
                    : 'Ready to answer'}{' '}
              </span>
            </div>
          </div>
        </section>

        <section className="chat-panel">
          <div className="chat-feed" aria-label="Conversation">
            {messages.map((item) => (
              <div
                key={item.id}
                className={
                  item.role === 'user'
                    ? 'message-row user'
                    : 'message-row assistant'
                }
              >
                <div
                  className={
                    item.role === 'user'
                      ? 'bubble user-bubble'
                      : 'bubble assistant-bubble'
                  }
                >
                  {item.text}
                </div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </div>

          <div className="composer">
            <label className="composer-input">
              <span className="sr-only">Type a message</span>
              <textarea
                value={message}
                onChange={(event) => setMessage(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === 'Enter' && !event.shiftKey) {
                    event.preventDefault();
                    sendMessage();
                  }
                }}
                rows={2}
                placeholder="Message your avatar..."
              />
            </label>
            <button
              type="button"
              className="primary-button send-button"
              onClick={sendMessage}
              disabled={isThinking}
            >
              {isThinking ? 'Sending...' : 'Send'}
            </button>
          </div>
        </section>

        <aside
          className={
            settingsOpen ? 'settings-drawer open' : 'settings-drawer closed'
          }
        >
          <div className="drawer-head">
            <div>
              <p className="eyebrow">Settings</p>
              <h2>Appearance and AI</h2>
            </div>
            <button
              type="button"
              className="close-button"
              onClick={() => setSettingsOpen(false)}
            >
              Close
            </button>
          </div>

          <div className="settings-group">
            <span>Day light</span>
            <button
              type="button"
              className="toggle-button"
              onClick={() => setIsDaylight((currentValue) => !currentValue)}
            >
              {isDaylight ? 'Light mode' : 'Dark mode'}
            </button>
          </div>

          <div className="settings-group">
            <span>Avatar</span>
            <div className="choice-row">
              {(['Man', 'Woman'] as AvatarGender[]).map((item) => (
                <button
                  key={item}
                  type="button"
                  className={
                    avatarGender === item
                      ? 'provider-pill active'
                      : 'provider-pill'
                  }
                  onClick={() => setAvatarGender(item)}
                >
                  {item}
                </button>
              ))}
            </div>
          </div>
          <div className="settings-group">
            <span>Avatar style</span>
            <div className="choice-row">
              {(['Photo', 'Realistic'] as AvatarMode[]).map((item) => (
                <button
                  key={item}
                  type="button"
                  className={
                    avatarMode === item
                      ? 'provider-pill active'
                      : 'provider-pill'
                  }
                  onClick={() => setAvatarMode(item)}
                >
                  {item}
                </button>
              ))}
            </div>
          </div>

          <div className="settings-group">
            <span>Voice type</span>
            <select
              value={voiceTone}
              onChange={(event) =>
                setVoiceTone(event.target.value as VoiceTone)
              }
            >
              {voiceTones.map((item) => (
                <option key={item} value={item}>
                  {item}
                </option>
              ))}
            </select>
          </div>

          <div className="settings-group">
            <span>Select model</span>
            <div className="choice-row">
              {providers.map((item) => (
                <button
                  key={item}
                  type="button"
                  className={
                    item === provider ? 'provider-pill active' : 'provider-pill'
                  }
                  onClick={() => setProvider(item)}
                >
                  {item}
                </button>
              ))}
            </div>
          </div>

          <label className="settings-group">
            <span>API key</span>
            <input
              type="password"
              value={apiKey}
              onChange={(event) => setApiKey(event.target.value)}
              placeholder="Paste selected provider key"
            />
          </label>

          {/* <div className="settings-preview">
            <span>Current mode</span>
            <strong>{response}</strong>
          </div> */}
        </aside>
      </main>
    </div>
  );
}

