               {isThinking ? 'Sending...' : 'Send'}
             </button>
           </div>
         </section>

         <aside
           className={
             settingsOpen ? 'settings-drawer open' : 'settings-drawer closed'
           }
         >
           <div className="drawer-head">
             <div>
               <p className="eyebrow">Settings</p>
               <h2>Appearance and AI</h2>
             </div>
             <button
               type="button"
               className="close-button"
               onClick={() => setSettingsOpen(false)}
             >
               Close
             </button>
           </div>

           <div className="settings-group">
             <span>Day light</span>
             <button
               type="button"
               className="toggle-button"
               onClick={() => setIsDaylight((currentValue) => !currentValue)}
             >
               {isDaylight ? 'Light mode' : 'Dark mode'}
             </button>
           </div>

           <div className="settings-group">
             <span>Avatar</span>
             <div className="choice-row">
               {(['Man', 'Woman'] as AvatarGender[]).map((item) => (
                 <button
                   key={item}
                   type="button"
                   className={
                     avatarGender === item
                       ? 'provider-pill active'
                       : 'provider-pill'
                   }
                   onClick={() => setAvatarGender(item)}
                 >
                   {item}
                 </button>
               ))}
             </div>
           </div>
           <div className="settings-group">
             <span>Avatar style</span>
             <div className="choice-row">
               {(['Photo', 'Realistic'] as AvatarMode[]).map((item) => (
                 <button
                   key={item}
                   type="button"
                   className={
                     avatarMode === item
                       ? 'provider-pill active'
                       : 'provider-pill'
                   }
                   onClick={() => setAvatarMode(item)}
                 >
                   {item}
                 </button>
               ))}
             </div>
           </div>

           <div className="settings-group">
             <span>Voice type</span>
             <select
               value={voiceTone}
               onChange={(event) =>
                 setVoiceTone(event.target.value as VoiceTone)
               }
             >
               {voiceTones.map((item) => (
                 <option key={item} value={item}>
                   {item}
                 </option>
               ))}
             </select>
           </div>

           <div className="settings-group">
             <span>Select model</span>
             <div className="choice-row">
               {providers.map((item) => (
                 <button
                   key={item}
                   type="button"
                   className={
                     item === provider ? 'provider-pill active' : 'provider-pill'
                   }
                   onClick={() => setProvider(item)}
                 >
                   {item}
                 </button>
               ))}
             </div>
           </div>

           <label className="settings-group">
             <span>API key</span>
             <input
               type="password"
               value={apiKey}
               onChange={(event) => setApiKey(event.target.value)}
               placeholder="Paste selected provider key"
             />
           </label>

           {/* <div className="settings-preview">
             <span>Current mode</span>
             <strong>{response}</strong>
           </div> */}
         </aside>
       </main>
     </div>
   );
 }

