import { useAnimations, useFBX, useGLTF } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import React, { useEffect, useRef, useState } from "react";
import * as THREE from "three";

// Visemes we cycle through while talking, in a natural-ish rotation.
const TALK_CYCLE = [
  "viseme_PP",
  "viseme_AA",
  "viseme_O",
  "viseme_I",
  "viseme_FF",
  "viseme_AA",
];

const ALL_VISEMES = [
  "viseme_PP",
  "viseme_kk",
  "viseme_I",
  "viseme_AA",
  "viseme_O",
  "viseme_U",
  "viseme_FF",
  "viseme_TH",
];

const CYCLE_INTERVAL_SECONDS = 0.14;

export function Avatar({ isSpeaking = false, ...props }) {
  const { nodes, materials } = useGLTF("/models/avatar.glb");
  const { animations: idleAnimation } = useFBX("/animations/Idle.fbx");
  idleAnimation[0].name = "Idle";

  const group = useRef();
  const { actions } = useAnimations([idleAnimation[0]], group);

  const cycleIndexRef = useRef(0);
  const cycleTimerRef = useRef(0);
  const [morphSmoothing] = useState(0.4);

  useEffect(() => {
    actions.Idle?.reset().fadeIn(0.5).play();
    return () => actions.Idle?.fadeOut(0.5);
  }, [actions]);

  const setViseme = (name, targetValue) => {
    const head = nodes.Wolf3D_Head;
    const teeth = nodes.Wolf3D_Teeth;
    if (!head?.morphTargetDictionary || !teeth?.morphTargetDictionary) return;

    const headIndex = head.morphTargetDictionary[name];
    const teethIndex = teeth.morphTargetDictionary[name];
    if (headIndex === undefined || teethIndex === undefined) return;

    head.morphTargetInfluences[headIndex] = THREE.MathUtils.lerp(
      head.morphTargetInfluences[headIndex],
      targetValue,
      morphSmoothing
    );
    teeth.morphTargetInfluences[teethIndex] = THREE.MathUtils.lerp(
      teeth.morphTargetInfluences[teethIndex],
      targetValue,
      morphSmoothing
    );
  };

  useFrame((state, deltaTime) => {
    if (isSpeaking) {
      cycleTimerRef.current += deltaTime;
      if (cycleTimerRef.current >= CYCLE_INTERVAL_SECONDS) {
        cycleTimerRef.current = 0;
        cycleIndexRef.current = (cycleIndexRef.current + 1) % TALK_CYCLE.length;
      }

      const activeViseme = TALK_CYCLE[cycleIndexRef.current];
      ALL_VISEMES.forEach((viseme) => {
        setViseme(viseme, viseme === activeViseme ? 1 : 0);
      });
    } else {
      ALL_VISEMES.forEach((viseme) => setViseme(viseme, 0));
    }

    // Gentle head turn toward camera, kept from the original tutorial.
    const head = group.current?.getObjectByName("Head");
    if (head) {
      head.lookAt(state.camera.position);
    }
  });

  return (
    <group {...props} dispose={null} ref={group}>
      <primitive object={nodes.Hips} />
      <skinnedMesh
        geometry={nodes.Wolf3D_Body.geometry}
        material={materials.Wolf3D_Body}
        skeleton={nodes.Wolf3D_Body.skeleton}
      />
      <skinnedMesh
        geometry={nodes.Wolf3D_Outfit_Bottom.geometry}
        material={materials.Wolf3D_Outfit_Bottom}
        skeleton={nodes.Wolf3D_Outfit_Bottom.skeleton}
      />
      <skinnedMesh
        geometry={nodes.Wolf3D_Outfit_Footwear.geometry}
        material={materials.Wolf3D_Outfit_Footwear}
        skeleton={nodes.Wolf3D_Outfit_Footwear.skeleton}
      />
      <skinnedMesh
        geometry={nodes.Wolf3D_Outfit_Top.geometry}
        material={materials.Wolf3D_Outfit_Top}
        skeleton={nodes.Wolf3D_Outfit_Top.skeleton}
      />
      <skinnedMesh
        geometry={nodes.Wolf3D_Hair.geometry}
        material={materials.Wolf3D_Hair}
        skeleton={nodes.Wolf3D_Hair.skeleton}
      />
      <skinnedMesh
        name="EyeLeft"
        geometry={nodes.EyeLeft.geometry}
        material={materials.Wolf3D_Eye}
        skeleton={nodes.EyeLeft.skeleton}
        morphTargetDictionary={nodes.EyeLeft.morphTargetDictionary}
        morphTargetInfluences={nodes.EyeLeft.morphTargetInfluences}
      />
      <skinnedMesh
        name="EyeRight"
        geometry={nodes.EyeRight.geometry}
        material={materials.Wolf3D_Eye}
        skeleton={nodes.EyeRight.skeleton}
        morphTargetDictionary={nodes.EyeRight.morphTargetDictionary}
        morphTargetInfluences={nodes.EyeRight.morphTargetInfluences}
      />
      <skinnedMesh
        name="Wolf3D_Head"
        geometry={nodes.Wolf3D_Head.geometry}
        material={materials.Wolf3D_Skin}
        skeleton={nodes.Wolf3D_Head.skeleton}
        morphTargetDictionary={nodes.Wolf3D_Head.morphTargetDictionary}
        morphTargetInfluences={nodes.Wolf3D_Head.morphTargetInfluences}
      />
      <skinnedMesh
        name="Wolf3D_Teeth"
        geometry={nodes.Wolf3D_Teeth.geometry}
        material={materials.Wolf3D_Teeth}
        skeleton={nodes.Wolf3D_Teeth.skeleton}
        morphTargetDictionary={nodes.Wolf3D_Teeth.morphTargetDictionary}
        morphTargetInfluences={nodes.Wolf3D_Teeth.morphTargetInfluences}
      />
    </group>
  );
}

