export type StockStatus = "in_stock" | "out_of_stock";

export type Product = {
  id: string;
  name: string;
  description: string;
  category: string;
  price: number;
  currency: string;
  stockStatus: StockStatus;
  deliveryEstimate: string;
};

export type ListProductsArgs = {
  keyword?: string;
