+const MAX_AUDIO_BYTES = 10 * 1024 * 1024;
+const supportedFormats = new Map([
+  ["audio/mpeg", "mp3"],
+  ["audio/mp3", "mp3"],
+  ["audio/wav", "wav"],
+  ["audio/x-wav", "wav"],
+  ["audio/wave", "wav"],
+]);
+
+export const runtime = "nodejs";
