    role: "user",
    content: [
      {
        type: "input_audio",
        input_audio: { data: audio.data, format: audio.format },
      },
    ],
  });

  const client = new OpenAI();
  for (let round = 0; round < MAX_TOOL_ROUNDS; round += 1) {
