.page {
  min-height: 100svh;
  padding: 32px 20px;
  background:
    radial-gradient(circle at 8% 8%, rgba(221, 193, 157, 0.3), transparent 34%),
    radial-gradient(circle at 92% 90%, rgba(137, 171, 177, 0.25), transparent 34%),
    #f6f3ed;
  color: #233238;
}

.shell {
  width: min(100%, 860px);
  min-height: calc(100svh - 64px);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(35, 50, 56, 0.12);
  border-radius: 28px;
  background: rgba(255, 253, 249, 0.85);
  box-shadow: 0 24px 70px rgba(49, 55, 48, 0.12);
  overflow: hidden;
}

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 40px 44px 28px;
  border-bottom: 1px solid rgba(35, 50, 56, 0.1);
}

.eyebrow {
  margin-bottom: 10px;
  color: #9c6847;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.header h1 {
  font-size: clamp(2rem, 5vw, 3.8rem);
  line-height: 0.98;
  letter-spacing: -0.06em;
}

.subtitle {
  margin-top: 16px;
  color: #687478;
  font-size: 1rem;
}

.status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  padding: 8px 12px;
  border-radius: 999px;
  background: #e7f0eb;
  color: #42705a;
  font-size: 0.78rem;
  font-weight: 700;
}

.statusDot,
.recordDot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #4a9b70;
}

.conversation {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-height: 280px;
  padding: 28px 44px;
  overflow-y: auto;
}

.emptyState {
  display: grid;
  place-items: center;
  align-content: center;
  flex: 1;
  min-height: 250px;
  text-align: center;
}

.waveform {
  margin-bottom: 18px;
  color: #b57b55;
  font-size: 2rem;
  letter-spacing: 0.3em;
}

.emptyState h2 {
  font-size: 1.2rem;
}

.emptyState p {
  max-width: 360px;
  margin-top: 8px;
  color: #788487;
  line-height: 1.5;
}

.message {
  max-width: 75%;
  padding: 14px 17px;
  border-radius: 18px;
  line-height: 1.5;
}

.messageLabel {
  display: block;
  margin-bottom: 5px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.message p {
  white-space: pre-wrap;
}

.customerMessage {
  align-self: flex-end;
  border-bottom-right-radius: 5px;
  background: #dce9e5;
  color: #31534c;
}

.agentMessage {
  align-self: flex-start;
  border-bottom-left-radius: 5px;
  background: #f0e7dc;
  color: #493d35;
}

.thinking span {
  animation: blink 1.2s infinite;
}

.thinking span:nth-child(2) { animation-delay: 0.2s; }
.thinking span:nth-child(3) { animation-delay: 0.4s; }

@keyframes blink {
  0%, 60%, 100% { opacity: 0.25; }
  30% { opacity: 1; }
}

.composer {
  padding: 24px 44px 30px;
  border-top: 1px solid rgba(35, 50, 56, 0.1);
}

.fileRow,
.selectedRow {
  display: flex;
  align-items: center;
  gap: 12px;
}

.uploadButton,
.recordButton,
