   border-bottom-right-radius: 5px;
   background: #dce9e5;
   color: #31534c;
 }

 .agentMessage {
   align-self: flex-start;
   border-bottom-left-radius: 5px;
   background: #f0e7dc;
   color: #493d35;
 }

 .thinking span {
   animation: blink 1.2s infinite;
 }

 .thinking span:nth-child(2) { animation-delay: 0.2s; }
 .thinking span:nth-child(3) { animation-delay: 0.4s; }

 @keyframes blink {
   0%, 60%, 100% { opacity: 0.25; }
   30% { opacity: 1; }
 }

 .composer {
   padding: 24px 44px 30px;
   border-top: 1px solid rgba(35, 50, 56, 0.1);
 }

 .fileRow,
 .selectedRow {
   display: flex;
   align-items: center;
   gap: 12px;
 }

 .uploadButton,
 .recordButton,
 .sendButton {
   min-height: 44px;
   border: 1px solid rgba(35, 50, 56, 0.16);
   border-radius: 12px;
   font: inherit;
   font-weight: 700;
   cursor: pointer;
 }

 .uploadButton {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   padding: 0 15px;
   background: #233238;
   color: #fff;
 }

 .uploadButton span {
   font-size: 1.3rem;
   font-weight: 400;
 }

 .uploadButton input {
   display: none;
 }

 .recordButton {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   padding: 0 15px;
   background: transparent;
   color: #40545a;
 }

 .recordButton.recording {
   border-color: #b45c52;
   color: #a04940;
 }

 .recording .recordDot {
   background: #c7584d;
   box-shadow: 0 0 0 5px rgba(199, 88, 77, 0.13);
 }

 .selectedRow {
   justify-content: space-between;
   margin-top: 14px;
   padding: 10px 0 0;
 }

 .fileName,
 .filePlaceholder {
   min-width: 0;
   overflow: hidden;
   color: #526267;
   font-size: 0.88rem;
   text-overflow: ellipsis;
   white-space: nowrap;
 }

 .filePlaceholder {
   color: #9aa3a3;
 }

 .sendButton {
   display: inline-flex;
   align-items: center;
   gap: 10px;
   flex-shrink: 0;
   padding: 0 17px;
   background: #b57b55;
   color: #fff;
 }

 .sendButton:disabled,
 .recordButton:disabled {
   cursor: not-allowed;
   opacity: 0.45;
 }

 .error,
 .notice {
   margin-top: 14px;
   font-size: 0.82rem;
   line-height: 1.4;
 }

 .error { color: #a04940; }
 .notice { color: #86622e; }

 .privacyNote {
   margin-top: 18px;
   color: #97a0a0;
   font-size: 0.72rem;
   text-align: center;
 }

 @media (max-width: 600px) {
   .page { padding: 0; }
   .shell { min-height: 100svh; border: 0; border-radius: 0; }
   .header, .conversation, .composer { padding-left: 22px; padding-right: 22px; }
   .header { padding-top: 28px; }
   .status { display: none; }
   .message { max-width: 90%; }
   .fileRow { flex-wrap: wrap; }
   .selectedRow { align-items: flex-start; flex-direction: column; }
   .sendButton { width: 100%; justify-content: center; }
 }

