.page {
  --ink: #1c2927;
  --muted: #687571;
  --cream: #f5f2eb;
  min-height: 100svh;
  background: var(--cream);
  color: var(--ink);
}

.nav {
  width: min(1180px, calc(100% - 64px));
  height: 88px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.brand em, .sectionHeading h2 em, .voiceCopy h2 em { font-family: Georgia, "Times New Roman", serif; font-weight: 400; }
.brandMark {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  border-radius: 50%;
  background: var(--ink);
  color: var(--cream);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.05rem;
  font-style: italic;
}

.navLinks { display: flex; align-items: center; gap: 32px; color: var(--muted); font-size: 0.78rem; font-weight: 600; }
.navLinks a { transition: color 0.2s ease; }
.navLinks a:hover { color: var(--ink); }
.navAgentLink { display: inline-flex; gap: 8px; align-items: center; color: var(--ink); }
.navAgentLink span { color: #b36e4d; font-size: 0.85rem; }

.hero {
  width: min(1180px, calc(100% - 64px));
  min-height: 500px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.02fr 0.98fr;
  align-items: center;
  gap: 40px;
}

.kicker {
  margin-bottom: 16px;
  color: #b36e4d;
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.hero h1 {
  max-width: 610px;
  font-size: clamp(3.2rem, 6vw, 5.7rem);
  line-height: 0.94;
  letter-spacing: -0.075em;
  font-weight: 700;
}

.hero h1 span { color: #b36e4d; font-family: Georgia, "Times New Roman", serif; font-style: italic; font-weight: 400; }
.heroDescription { max-width: 380px; margin: 25px 0 30px; color: var(--muted); font-size: 1rem; line-height: 1.65; }
.primaryButton, .lightButton { display: inline-flex; align-items: center; justify-content: center; gap: 22px; min-height: 48px; padding: 0 20px; border-radius: 3px; background: var(--ink); color: #fff; font-size: 0.76rem; font-weight: 700; transition: transform 0.2s ease, background 0.2s ease; }
.primaryButton:hover, .lightButton:hover { transform: translateY(-2px); background: #324440; }

.heroArt { position: relative; min-height: 410px; overflow: hidden; border-radius: 2px; background: #dce5df; }
.artOrb { position: absolute; border-radius: 50%; filter: blur(1px); }
.orbOne { width: 330px; height: 330px; left: 10%; top: -8%; background: #eac1a3; }
.orbTwo { width: 270px; height: 270px; right: -10%; bottom: -16%; background: #a9c2bd; }
.artCard { position: absolute; left: 50%; top: 50%; width: 210px; height: 272px; transform: translate(-50%, -50%) rotate(7deg); display: flex; flex-direction: column; justify-content: space-between; padding: 23px; border: 1px solid rgba(28, 41, 39, 0.23); background: rgba(245, 242, 235, 0.82); box-shadow: 16px 18px 30px rgba(28, 41, 39, 0.1); }
.artSpark { align-self: flex-end; color: #b36e4d; font-size: 1.4rem; }
.artLabel { font-size: 0.62rem; letter-spacing: 0.17em; line-height: 1.5; }
.artLabel strong { font-size: 1.3rem; letter-spacing: 0.04em; }
.artLine { width: 44px; height: 1px; background: var(--ink); }
.artCaption { font-size: 0.55rem; font-weight: 700; letter-spacing: 0.18em; line-height: 1.5; }

.collection { width: min(1180px, calc(100% - 64px)); margin: 80px auto 110px; }
.sectionHeading { display: flex; justify-content: space-between; align-items: end; margin-bottom: 34px; }
.sectionHeading h2, .voiceCopy h2 { font-size: clamp(2rem, 4vw, 3.2rem); line-height: 0.98; letter-spacing: -0.06em; }
.sectionHeading h2 em, .voiceCopy h2 em { color: #b36e4d; }
.sectionNote { color: var(--muted); font-size: 0.75rem; line-height: 1.6; text-align: right; }
.productGrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 34px 20px; }
.productCard { min-width: 0; }
.productVisual { position: relative; width: 100%; aspect-ratio: 1.08; display: flex; align-items: center; justify-content: center; overflow: hidden; border: 0; cursor: pointer; color: #fff; background: #b7cfca; }
.productVisual::after, .modalVisual::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(28, 41, 39, 0.12), transparent 35%, rgba(28, 41, 39, 0.22)); pointer-events: none; }
.productVisual img, .modalVisual img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.45s ease; }
.productVisual:hover img, .productVisual:focus-visible img { transform: scale(1.05); }
.visualCategory { position: absolute; left: 17px; top: 15px; z-index: 1; font-size: 0.62rem; font-weight: 800; letter-spacing: 0.13em; text-transform: uppercase; }
.viewDetails { position: absolute; right: 16px; bottom: 15px; z-index: 1; opacity: 0; font-size: 0.68rem; font-weight: 700; transition: opacity 0.2s ease; }
.productVisual:hover .viewDetails, .productVisual:focus-visible .viewDetails { opacity: 1; }
.productInfo { padding-top: 15px; }
.productTitleRow { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.productInfo h3 { font-size: 0.95rem; letter-spacing: -0.02em; }
.productInfo p { min-height: 43px; margin: 8px 0 12px; color: var(--muted); font-size: 0.78rem; line-height: 1.5; }
.price { flex-shrink: 0; font-size: 0.85rem; font-weight: 700; }
.stock { display: inline-flex; align-items: center; gap: 6px; color: #4b8064; font-size: 0.68rem; font-weight: 700; }
.stock > span { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.outOfStock { color: #a86856; }

.voiceBanner { width: min(1180px, calc(100% - 64px)); min-height: 280px; margin: 0 auto 100px; display: flex; align-items: center; gap: 48px; padding: 48px 58px; background: var(--ink); color: var(--cream); }
.voiceIcon { display: grid; place-items: center; width: 92px; height: 92px; flex-shrink: 0; border: 1px solid rgba(245, 242, 235, 0.3); border-radius: 50%; color: #e5b89b; font-size: 1.2rem; letter-spacing: 0.13em; }
.voiceCopy { flex: 1; }
.voiceCopy .kicker { color: #e5b89b; }
.voiceCopy h2 em { color: #e5b89b; }
.voiceCopy > p:last-child { max-width: 400px; margin-top: 17px; color: #aeb9b3; font-size: 0.85rem; line-height: 1.6; }
.lightButton { flex-shrink: 0; background: var(--cream); color: var(--ink); }
.lightButton:hover { background: #fff; }

.footer { width: min(1180px, calc(100% - 64px)); min-height: 94px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; border-top: 1px solid rgba(28, 41, 39, 0.14); color: var(--muted); font-size: 0.7rem; }

.modalBackdrop { position: fixed; inset: 0; z-index: 10; display: grid; place-items: center; padding: 20px; background: rgba(28, 41, 39, 0.58); }
.modal { position: relative; width: min(700px, 100%); display: grid; grid-template-columns: 0.85fr 1.15fr; overflow: hidden; background: var(--cream); color: var(--ink); box-shadow: 0 25px 80px rgba(0, 0, 0, 0.25); }
.modalVisual { position: relative; display: grid; place-items: center; min-height: 340px; overflow: hidden; background: #b7cfca; }
.modalContent { padding: 48px 40px; }
.modalContent h2 { font-size: 2.2rem; line-height: 1; letter-spacing: -0.06em; }
.modalContent > p:not(.kicker):not(.delivery) { margin: 18px 0 25px; color: var(--muted); font-size: 0.9rem; line-height: 1.6; }
.modalMeta { display: flex; align-items: center; justify-content: space-between; padding: 16px 0; border-top: 1px solid rgba(28, 41, 39, 0.14); border-bottom: 1px solid rgba(28, 41, 39, 0.14); }
.modalMeta strong { font-size: 1.1rem; }
.delivery { margin: 15px 0 25px; color: var(--muted); font-size: 0.72rem; }
.closeButton { position: absolute; top: 14px; right: 16px; z-index: 2; width: 32px; height: 32px; border: 0; border-radius: 50%; background: rgba(245, 242, 235, 0.7); color: var(--ink); font-size: 1.4rem; line-height: 1; cursor: pointer; }

@media (max-width: 760px) {
  .nav, .hero, .collection, .voiceBanner, .footer { width: min(100% - 40px, 560px); }
  .nav { height: 72px; }
  .navLinks a:not(.navAgentLink) { display: none; }
  .navLinks { gap: 0; font-size: 0.68rem; }
  .hero { display: flex; flex-direction: column; align-items: stretch; gap: 35px; padding-top: 44px; }
  .heroArt { min-height: 300px; }
  .collection { margin-top: 70px; }
  .productGrid { grid-template-columns: repeat(2, 1fr); gap: 30px 14px; }
  .productInfo p { min-height: 0; }
  .voiceBanner { flex-direction: column; align-items: flex-start; gap: 25px; padding: 38px 28px; }
  .voiceIcon { width: 64px; height: 64px; }
  .lightButton { width: 100%; }
  .footer { min-height: 110px; flex-wrap: wrap; gap: 12px; padding: 22px 0; }
  .modal { grid-template-columns: 1fr; max-height: 90svh; overflow-y: auto; }
  .modalVisual { min-height: 200px; }
  .modalContent { padding: 30px 28px 35px; }
}

@media (max-width: 430px) {
  .nav, .hero, .collection, .voiceBanner, .footer { width: calc(100% - 32px); }
  .hero h1 { font-size: 3.25rem; }
  .sectionHeading { display: block; }
  .sectionNote { margin-top: 14px; text-align: left; }
  .productGrid { grid-template-columns: 1fr; }
  .productVisual { aspect-ratio: 1.25; }
}

